  "sim.egg-incubator.title": "卵の孵卵器",
  "sim.egg-incubator.desc": "孵化場で温度・湿度・卵の回転を管理し、孵化率を最大化します。",
  "sim.dairy-farm.title": "酪農場",
  "sim.dairy-farm.desc": "小規模な酪農を運営：給餌スケジュール、搾乳サイクル、群れの健康管理で生産量を最大化します。",
  "sim.poultry-farm.title": "養鶏場",
  "sim.poultry-farm.desc": "商業養鶏場を運営 — 鶏（ブロイラー・レイヤー）のための飼料、健康状態、生産目標を管理します。",
  "sim.cattle-dairy.title": "畜産＆酪農",
  "sim.cattle-dairy.desc": "牧場と酪農ユニットを管理し、放牧地の運用、繁殖、乳の生産のバランスを取ります。",
  "sim.sheep-farm.title": "羊の牧場",
  "sim.sheep-farm.desc": "季節サイクルで羊の牧場を運営：子羊の出産、剪毛、市場での販売。",
  "sim.network-noc.title": "Network NOC",
  "sim.network-noc.desc": "ネットワークオペレーションセンター（NOC）エンジニアとして行動し、プレッシャー下で進行中のインフラ障害を診断・解決します。",
  "sim.mobile-repair.title": "モバイル修理工房",
  "sim.mobile-repair.desc": "スマホを診断して修理—画面交換、バッテリー不良、マザーボード故障に対応します。",
  "sim.laptop-repair.title": "ノートパソコン修理工房",
  "sim.laptop-repair.desc": "ノートパソコンのトラブルシューティングと修理：ハードウェア不良、BIOSの問題、部品交換に対応します。",
  "sim.perfume-lab.title": "香水ラボ",
  "sim.perfume-lab.desc": "精油と香料をブレンドして、シグネチャーフレグランスを作り、品質基準を達成します。",
  "sim.detergent-lab.title": "洗剤ラボ",
  "sim.detergent-lab.desc": "洗浄製品を調合—界面活性剤、増量剤、性能テストのバランスを取りつつ、予算内で仕上げます。",
  "sim.skin-care-lab.title": "スキンケアラボ",
  "sim.skin-care-lab.desc": "化粧品の配合を開発・テストし、安全基準と有効性の目標を満たします。",
  "sim.woodworking.title": "木工ワークショップ",
  "sim.woodworking.desc": "オーダーメイドの木工工房を運営：作業を計画し、資材を管理し、家具を納期と予算どおりに仕上げます。",
  "sim.aluminum-glazing.title": "アルミ＆ガラス",
  "sim.aluminum-glazing.desc": "見積もりから現場完了まで、アルミ加工とガラス設置の事業を管理します。",
  "sim.global-kitchen.title": "グローバルキッチン",
  "sim.global-kitchen.desc": "レストランのキッチンをリード：メニュー、スタッフ、コスト、お客様満足を、営業シフトごとに管理します。",
  "sim.chocolate-factory.title": "チョコレート工場",
  "sim.chocolate-factory.desc": "製菓工場を運営—カカオの調達、製造スケジュール、品質管理を行います。",
  "sim.solar-energy.title": "太陽光エネルギープラント",
  "sim.solar-energy.desc": "太陽光設備を設計・運用—パネルの規模、系統への出力管理、投資対効果の追跡を行います。",
  "sim.hvac-systems.title": "空調（HVAC）システム",
  "sim.hvac-systems.desc": "商業施設向けに、暖房・換気・空調（空調設備）システムの設置と保守を行います。",
  "sim.logistics-supply.title": "物流＆サプライチェーン",
  "sim.logistics-supply.desc": "倉庫業務、車両ルート、取引先との関係を最適化し、納品KPIを達成します。",
  "sim.barber-salon.title": "理髪店（バーバーサロン）",
  "sim.barber-salon.desc": "理髪店を運営：予約管理、スタッフのシフト、料金、顧客の維持戦略を管理します。",
  "sim.board-surgeon.title": "外科医",
  "sim.board-surgeon.desc": "模擬手術室で、重大な外科的判断を行います—時間管理と患者安全に配慮します。",
  "sim.english-journey.title": "英語ジャーニー",
  "sim.english-journey.desc": "学習者を、構造化された英語プログラムに沿ってガイドし、さまざまなスキルレベルに合わせて調整します。",
  "sim.music-training.title": "音楽トレーニングスタジオ",
  "sim.music-training.desc": "音楽教室を運営：レッスンをスケジュールし、楽器を管理し、発表会に向けた生徒の進捗を追跡します。",
  "sim.trade-tycoon.title": "トレードタイクーン",
  "sim.trade-tycoon.desc": "トレーディング帝国を築く—安く買って高く売る。複数の市場で在庫とキャッシュフローを管理します。",
  "sim.vehicle-diagnostics.title": "車両診断＆修理シミュレーター",
  "sim.vehicle-diagnostics.desc": "OBD-IIの故障コードを診断し、電気系統の不具合を特定し、実環境の自動車修理ワークフローを管理します。",
  "sim.marine-vessel.title": "船舶追跡＆海上物流",
  "sim.marine-vessel.desc": "グローバルな艦隊を指揮—船舶を追跡し、港の混雑、天候による緊急事態、運河の遅延に対応します。",
