  "jungle.howTo.1": "ジャングルに取り残された—サバイバルの選択をしよう",
  "jungle.howTo.2": "各選択はHPとスコアにそれぞれ異なる影響を与える",
  "jungle.howTo.3": "HPが0になるとゲームは終了する",
  "jungle.howTo.4": "8つのシナリオすべてを生き延びて勝利！",
  "jungle.scene6": "負傷した鳥を見つけた。どうする？",
  "jungle.s6c1": "慎重に運ぶ—道が開けるかも（+5 HP、+25 pts）",
  "jungle.s6c2": "放っておく—世話をするとエネルギーを消費する（0 HP、+10 pts）",
  "jungle.scene7": "川が行く手を遮る。水は速そうだ。",
  "jungle.s7c1": "倒木でいかだを作る（−5 HP、+40 pts）",
  "jungle.s7c2": "上流へ歩いて浅瀬を探す（+10 HP、+20 pts）",
  "jungle.scene8": "遠くに煙が見える。",
  "jungle.s8c1": "煙の方へ向かう—救助かもしれない！（+15 HP、+45 pts）",
  "jungle.s8c2": "避ける—山火事の可能性（−5 HP、+15 pts）",
  "jungle.scene9": "夜が来た。身を守る場所が必要だ。",
  "jungle.s9c1": "高い木に登って捕食者から身を守る（+10 HP、+30 pts）",
  "jungle.s9c2": "枝で地面のシェルターを作る（−5 HP、+35 pts）",
  "jungle.scene10": "見覚えのない果物を見つけた。とても空腹だ。",
  "jungle.s10c1": "食べる—飢えてる！（−20 HP、+30 pts）",
  "jungle.s10c2": "まずは少量を肌で試す（0 HP、+20 pts）",
  "jungle.scene11": "大きなヘビが道で丸まっている。",
  "jungle.s11c1": "ゆっくり後ずさりして迂回路を探す（+5 HP、+30 pts）",
  "jungle.s11c2": "追い払おうとする（−25 HP、+40 pts）",
  "jungle.scene12": "滝の音が聞こえる—水の備えが致命的に少ない。",
  "jungle.s12c1": "音に沿って進み、新鮮な水を見つける（+20 HP、+35 pts）",
  "jungle.s12c2": "無視して前進する（−15 HP、+20 pts）",
  "jungle.scene13": "嵐が急速に近づいている。",
  "jungle.s13c1": "高い場所を見つけて身を隠す（+10 HP、+25 pts）",
  "jungle.s13c2": "逃げるために動き続ける（−10 HP、+30 pts）",
  "jungle.scene14": "洞窟を見つけた。暗くなってきている。",
  "jungle.s14c1": "洞窟に入って身を守る（+15 HP、+30 pts）",
  "jungle.s14c2": "木の下で眠る—洞窟が使用中かもしれない（+5 HP、+20 pts）",
  "jungle.scene15": "疲れ果てた。前方の開けた場所は安全そうだ。",
  "jungle.s15c1": "休んで回復する（+20 HP、+20 pts）",
  "jungle.s15c2": "押し進める—ここで休むのは危険だ（−5 HP、+30 pts）",
  "jungle.scene16": "木に彫られた古い地図を見つけた。",
  "jungle.s16c1": "地図の指す方向へ進む（+5 HP、+40 pts）",
  "jungle.s16c2": "無視する—古い可能性がある（0 HP、+10 pts）",
  "jungle.scene17": "野生のイノシシが、攻撃的に行く手を横切る。",
  "jungle.s17c1": "すぐに最寄りの木に登る（+5 HP、+30 pts）",
  "jungle.s17c2": "その場に踏みとどまり叫ぶ（−20 HP、+35 pts）",
  "jungle.scene18": "物資のある放棄されたキャンプを見つけた。",
  "jungle.s18c1": "使えそうなものを全部持ち帰る（+20 HP、+50 pts）",
  "jungle.s18c2": "置いていく—あとで誰かが必要になるかもしれない（0 HP、+10 pts）",
  "jungle.scene19": "猿があなたの食料袋を盗んだ！",
  "jungle.s19c1": "猿を追いかける（−10 HP、+40 pts）",
  "jungle.s19c2": "放っておく—エネルギーの無駄だ（+0 HP、+15 pts）",
  "jungle.scene20": "頭上でヘリコプターの音がする。",
  "jungle.s20c1": "合図の焚き火をすぐに！（+30 HP、+60 pts）",
  "jungle.s20c2": "腕を振る—見つけてもらえるかもしれない（+5 HP、+40 pts）",
