  "kids.explorer.eco.bottle.trash": "そのまま一般ゴミに捨てる",
  "kids.explorer.eco.bottle.explain": "プラスチックボトルをリサイクルすると資源を節約でき、埋め立て地や海から守れます。",
  "kids.explorer.eco.bottle.explainWrong": "プラスチックボトルは新しいものにリサイクルできます。次はリサイクルボックスを使ってみて！",
  "kids.explorer.eco.tap.prompt": "歯みがきは終わりました。まだ水が流れています。あなたはどうしますか？",
  "kids.explorer.eco.tap.close": "水を止める",
  "kids.explorer.eco.tap.leave": "そのまま流し続ける",
  "kids.explorer.eco.tap.explain": "水を止めるだけで、毎日たくさんのきれいな水を節約できます。",
  "kids.explorer.eco.tap.explainWrong": "流しっぱなしの水道は多くの水（何リットルも）を無駄にします。使っていないときは止めましょう。",
  "kids.explorer.eco.lights.prompt": "部屋を出ます。明かりがついています。あなたはどうしますか？",
  "kids.explorer.eco.lights.off": "明かりを消す",
  "kids.explorer.eco.lights.on": "そのままつけておく",
  "kids.explorer.eco.lights.explain": "部屋を出るときに明かりを消すと、省エネになります。",
  "kids.explorer.eco.lights.explainWrong": "人のいない部屋でつけっぱなしの照明は、電気を無駄にします。",
  "kids.explorer.eco.ride.prompt": "近くの場所に行く必要があります。どうやって行きますか？",
  "kids.explorer.eco.ride.bike": "自転車に乗るか、歩く",
  "kids.explorer.eco.ride.car": "車で送ってもらうよう頼む",
  "kids.explorer.eco.ride.explain": "短い移動を歩いたり自転車にしたりすると、汚染は発生しません。",
  "kids.explorer.eco.ride.explainWrong": "車は燃料を使い、汚染を生みます。短い移動なら歩くか自転車のほうがきれいです。",
  "kids.explorer.eco.tree.prompt": "学校で庭を作ろうとしています。何を入れるべきでしょうか？",
  "kids.explorer.eco.tree.plant": "新しい木を植える",
  "kids.explorer.eco.tree.cut": "古い木を切り倒す",
  "kids.explorer.eco.tree.explain": "木は空気をきれいにし、動物の住みかにもなります。もっと植えることはみんなのためになります。",
  "kids.explorer.eco.tree.explainWrong": "木は空気をきれいにしてくれます。切り倒すのではなく、もっと植えるべきです。",
  "kids.explorer.eco.bag.prompt": "買い物に行きます。どんな袋を持っていきますか？",
  "kids.explorer.eco.bag.reusable": "繰り返し使える布バッグ",
  "kids.explorer.eco.bag.plastic": "毎回新しいプラスチック袋",
  "kids.explorer.eco.bag.explain": "繰り返し使えるバッグなら、長い目で見てプラスチックごみが大幅に減ります。",
  "kids.explorer.eco.bag.explainWrong": "使い捨てのプラスチック袋は大量のごみを生みます。繰り返し使える袋のほうがより良いです。",
  "kids.explorer.eco.animal.prompt": "木の上で野鳥の巣を見つけました。あなたはどうしますか？",
  "kids.explorer.eco.animal.protect": "そっとして、距離を取って観察する",
  "kids.explorer.eco.animal.ignore": "巣や卵に触る",
  "kids.explorer.eco.animal.explain": "野生の動物は、家を乱さずに見守ってくれると一番安心です。",
  "kids.explorer.eco.animal.explainWrong": "野生の巣に触ると、親鳥が驚いて離れてしまうことがあります。観察するだけがいちばんです。",
  "kids.explorer.eco.solar.prompt": "町が新しい電源を選んでいます。地球にとってどちらが良いですか？",
