  "kids.explorer.eco.solar.coal": "石炭を燃やす",
  "kids.explorer.eco.solar.explain": "ソーラーエネルギーはクリーンで再生可能です。汚染を生む石炭とは違います。",
  "kids.explorer.eco.solar.explainWrong": "石炭を燃やすと汚染が発生します。ソーラーのようなクリーンなエネルギーのほうが、地球には良いです。",
